package com.minewaku.chatter.identityaccess.infrastructure.user;
import java.time.*; import java.util.*; import org.springframework.context.annotation.*; import org.springframework.core.convert.converter.*; import org.springframework.data.jdbc.repository.config.EnableJdbcRepositories; import org.springframework.data.jdbc.repository.config.AbstractJdbcConfiguration; import org.springframework.data.convert.*; import com.minewaku.chatter.identityaccess.user.internal.model.*;
@Configuration @EnableJdbcRepositories(basePackages="com.minewaku.chatter.identityaccess.user.internal.port") public class JdbcUserAccountConfiguration extends AbstractJdbcConfiguration { @Override protected List<?> userConverters(){return List.of(UserIdToLong.INSTANCE,LongToUserId.INSTANCE,EmailToString.INSTANCE,StringToEmail.INSTANCE,UsernameToString.INSTANCE,StringToUsername.INSTANCE,BirthdayToDate.INSTANCE,DateToBirthday.INSTANCE,StatusToString.INSTANCE,StringToStatus.INSTANCE);} @WritingConverter enum UserIdToLong implements Converter<UserId,Long>{INSTANCE;public Long convert(UserId v){return v.value();}} @ReadingConverter enum LongToUserId implements Converter<Long,UserId>{INSTANCE;public UserId convert(Long v){return new UserId(v);}} @WritingConverter enum EmailToString implements Converter<Email,String>{INSTANCE;public String convert(Email v){return v.value();}} @ReadingConverter enum StringToEmail implements Converter<String,Email>{INSTANCE;public Email convert(String v){return new Email(v);}} @WritingConverter enum UsernameToString implements Converter<Username,String>{INSTANCE;public String convert(Username v){return v.value();}} @ReadingConverter enum StringToUsername implements Converter<String,Username>{INSTANCE;public Username convert(String v){return new Username(v);}} @WritingConverter enum BirthdayToDate implements Converter<Birthday,LocalDate>{INSTANCE;public LocalDate convert(Birthday v){return v.value();}} @ReadingConverter enum DateToBirthday implements Converter<LocalDate,Birthday>{INSTANCE;public Birthday convert(LocalDate v){return new Birthday(v);}} @WritingConverter enum StatusToString implements Converter<AccountStatus,String>{INSTANCE;public String convert(AccountStatus v){return v.name();}} @ReadingConverter enum StringToStatus implements Converter<String,AccountStatus>{INSTANCE;public AccountStatus convert(String v){return AccountStatus.valueOf(v);}} }